{
  "tasks": [
    {
      "task_id": "T1",
      "title": "已解决工单优先级分布 Top 2",
      "business_question": "在只看已解决工单的条件下，统计各优先级的工单数量，并按数量降序取前两名。",
      "priority": "P0",
      "priority_reason": "直接回答核心问题：已解决工单中各优先级的数量排名。删除此任务将无法支持关于高优先级工单集中度的决策。",
      "requirement_ids": [
        "C01",
        "C02",
        "C03",
        "C04"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S1",
          "operation": "filter",
          "params": {
            "conditions": [
              {
                "field": "field_0003",
                "operator": "eq",
                "value": "已解决"
              }
            ]
          }
        },
        {
          "step_id": "S2",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "ticket_count"
              }
            ],
            "dimensions": [
              "field_0004"
            ]
          }
        },
        {
          "step_id": "S3",
          "operation": "top_n",
          "params": {
            "field": "ticket_count",
            "direction": "desc",
            "n": 2
          }
        }
      ]
    }
  ]
